"""LRU cache with per-entry time-to-live."""

import time
from collections import OrderedDict


class TTLCache:
    """A fixed-capacity LRU cache where each entry may have its own TTL."""

    def __init__(self, capacity, clock=time.monotonic):
        if capacity < 1:
            raise ValueError("capacity must be >= 1")
        self._capacity = capacity
        self._clock = clock
        # key -> (value, expires_at) where expires_at is None for no expiry
        self._data = OrderedDict()
        self._expires = {}

    # -- helpers ---------------------------------------------------------
    def _expired(self, key):
        expires_at = self._expires.get(key)
        if expires_at is None:
            return False
        return self._clock() >= expires_at

    def _remove(self, key):
        self._data.pop(key, None)
        self._expires.pop(key, None)

    # -- public API ------------------------------------------------------
    def put(self, key, value, ttl=None):
        if ttl is not None and ttl <= 0:
            raise ValueError("ttl must be > 0 or None")

        now = self._clock()

        if key not in self._data:
            if len(self._data) >= self._capacity:
                self.evict_expired()
            if len(self._data) >= self._capacity:
                oldest, _ = self._data.popitem(last=False)
                self._expires.pop(oldest, None)

        self._data[key] = value
        self._data.move_to_end(key)
        self._expires[key] = None if ttl is None else now + ttl

    def get(self, key, default=None):
        if key not in self._data:
            return default
        if self._expired(key):
            self._remove(key)
            return default
        self._data.move_to_end(key)
        return self._data[key]

    def __contains__(self, key):
        if key not in self._data:
            return False
        if self._expired(key):
            self._remove(key)
            return False
        return True

    def __len__(self):
        self.evict_expired()
        return len(self._data)

    def keys(self):
        self.evict_expired()
        return list(self._data.keys())

    def evict_expired(self):
        now = self._clock()
        expired = [
            key
            for key, expires_at in self._expires.items()
            if expires_at is not None and now >= expires_at
        ]
        for key in expired:
            self._remove(key)
        return len(expired)

"""Half-open integer interval utilities.

An interval is a pair ``(start, end)`` of integers meaning the half-open
range ``[start, end)``.  A pair with ``start >= end`` is empty and is ignored
everywhere.  Inputs may be lists or tuples of pairs in any order.
"""

from typing import Iterable, List, Sequence, Tuple


def _clean(intervals: Iterable[Sequence[int]]) -> List[Tuple[int, int]]:
    """Return the non-empty intervals as tuples sorted by (start, end)."""
    out: List[Tuple[int, int]] = []
    for pair in intervals:
        start, end = pair[0], pair[1]
        if start < end:
            out.append((start, end))
    out.sort()
    return out


def merge(intervals: Iterable[Sequence[int]]) -> List[Tuple[int, int]]:
    """Merge overlapping and touching intervals; nested ones collapse."""
    cleaned = _clean(intervals)
    if not cleaned:
        return []

    merged: List[Tuple[int, int]] = []
    cur_start, cur_end = cleaned[0]
    for start, end in cleaned[1:]:
        if start <= cur_end:  # overlapping or touching
            if end > cur_end:
                cur_end = end
        else:
            merged.append((cur_start, cur_end))
            cur_start, cur_end = start, end
    merged.append((cur_start, cur_end))
    return merged


def free_gaps(
    intervals: Iterable[Sequence[int]], window: Sequence[int]
) -> List[Tuple[int, int]]:
    """Maximal sub-ranges of ``window`` not covered by any interval."""
    ws, we = window[0], window[1]
    if ws >= we:
        return []

    clipped: List[Tuple[int, int]] = []
    for pair in intervals:
        start, end = pair[0], pair[1]
        start = max(start, ws)
        end = min(end, we)
        if start < end:
            clipped.append((start, end))
    if not clipped:
        return [(ws, we)]

    merged = merge(clipped)

    gaps: List[Tuple[int, int]] = []
    cursor = ws
    for start, end in merged:
        if start > cursor:
            gaps.append((cursor, start))
        if end > cursor:
            cursor = end
    if cursor < we:
        gaps.append((cursor, we))
    return gaps


def max_overlap(intervals: Iterable[Sequence[int]]) -> int:
    """Largest number of intervals covering one common point."""
    events: List[Tuple[int, int]] = []
    for pair in intervals:
        start, end = pair[0], pair[1]
        if start < end:
            events.append((start, 1))
            events.append((end, -1))
    if not events:
        return 0
    # Sort by position; for equal positions process ends before starts.
    events.sort(key=lambda item: (item[0], item[1]))

    best = 0
    current = 0
    for _, delta in events:
        current += delta
        if current > best:
            best = current
    return best

"""Arithmetic expression evaluator.

Implements a tokenizer plus a recursive-descent (precedence-climbing) parser
for a small arithmetic language. No eval/exec/compile/ast is used.
"""

import re

__all__ = ["evaluate"]

_TOKEN_RE = re.compile(
    r"""
    (?P<space>\s+)
  | (?P<number>\d+\.\d+|\.\d+|\d+)
  | (?P<name>[A-Za-z_][A-Za-z_0-9]*)
  | (?P<op>\*\*|//|[+\-*/%(),])
    """,
    re.VERBOSE,
)

_FUNCTIONS = {"min", "max", "abs"}


def _tokenize(text):
    tokens = []
    pos = 0
    length = len(text)
    while pos < length:
        match = _TOKEN_RE.match(text, pos)
        if match is None:
            raise ValueError("unexpected character %r at position %d" % (text[pos], pos))
        kind = match.lastgroup
        value = match.group()
        pos = match.end()
        if kind == "space":
            continue
        tokens.append((kind, value))
    tokens.append(("end", ""))
    return tokens


class _Parser:
    def __init__(self, tokens):
        self.tokens = tokens
        self.index = 0

    def peek(self):
        return self.tokens[self.index]

    def advance(self):
        token = self.tokens[self.index]
        self.index += 1
        return token

    def expect(self, kind, value=None):
        token = self.peek()
        if token[0] != kind or (value is not None and token[1] != value):
            raise ValueError("expected %r, found %r" % (value or kind, token[1]))
        return self.advance()

    # expression := term (('+' | '-') term)*
    def parse_expression(self):
        value = self.parse_term()
        while True:
            token = self.peek()
            if token[0] == "op" and token[1] in ("+", "-"):
                self.advance()
                right = self.parse_term()
                value = value + right if token[1] == "+" else value - right
            else:
                return value

    # term := factor (('*' | '/' | '//' | '%') factor)*
    def parse_term(self):
        value = self.parse_factor()
        while True:
            token = self.peek()
            if token[0] == "op" and token[1] in ("*", "/", "//", "%"):
                self.advance()
                right = self.parse_factor()
                if token[1] == "*":
                    value = value * right
                elif token[1] == "/":
                    value = value / right
                elif token[1] == "//":
                    value = value // right
                else:
                    value = value % right
            else:
                return value

    # factor := ('+' | '-') factor | power
    def parse_factor(self):
        token = self.peek()
        if token[0] == "op" and token[1] in ("+", "-"):
            self.advance()
            operand = self.parse_factor()
            return operand if token[1] == "+" else -operand
        return self.parse_power()

    # power := atom ('**' factor)?   (right-associative, looser than unary)
    def parse_power(self):
        base = self.parse_atom()
        token = self.peek()
        if token[0] == "op" and token[1] == "**":
            self.advance()
            exponent = self.parse_factor()
            return base ** exponent
        return base

    # atom := number | '(' expression ')' | name '(' args ')'
    def parse_atom(self):
        token = self.peek()
        if token[0] == "number":
            self.advance()
            text = token[1]
            if "." in text:
                return float(text)
            return int(text)
        if token[0] == "name":
            return self.parse_call()
        if token[0] == "op" and token[1] == "(":
            self.advance()
            value = self.parse_expression()
            self.expect("op", ")")
            return value
        raise ValueError("unexpected token %r" % (token[1],))

    def parse_call(self):
        token = self.advance()
        name = token[1]
        if name not in _FUNCTIONS:
            raise ValueError("unknown name %r" % (name,))
        self.expect("op", "(")
        args = [self.parse_expression()]
        while self.peek()[0] == "op" and self.peek()[1] == ",":
            self.advance()
            args.append(self.parse_expression())
        self.expect("op", ")")
        if name == "abs":
            if len(args) != 1:
                raise ValueError("abs() takes exactly one argument")
            return abs(args[0])
        if name == "min":
            return min(args)
        return max(args)


def evaluate(text):
    if not isinstance(text, str):
        raise ValueError("expression must be a string")
    tokens = _tokenize(text)
    parser = _Parser(tokens)
    value = parser.parse_expression()
    token = parser.peek()
    if token[0] != "end":
        raise ValueError("unexpected trailing token %r" % (token[1],))
    return value
